BEGIN;
CREATE TABLE IF NOT EXISTS tenant.crm_partner_portal_profiles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,partner_party_id uuid,display_name text NOT NULL,status text NOT NULL DEFAULT 'active' CHECK(status IN('invited','active','suspended','inactive')),permissions jsonb NOT NULL DEFAULT '[]'::jsonb,last_login_at timestamptz,created_by uuid REFERENCES public.users(id) ON DELETE SET NULL,updated_by uuid REFERENCES public.users(id) ON DELETE SET NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(organization_id,partner_party_id));
CREATE TABLE IF NOT EXISTS tenant.crm_partner_deal_registrations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,partner_party_id uuid,account_name text NOT NULL,account_domain text,opportunity_name text NOT NULL,estimated_value numeric(18,2) NOT NULL DEFAULT 0,currency_code char(3),status text NOT NULL DEFAULT 'submitted' CHECK(status IN('draft','submitted','approved','rejected','expired','converted')),conflict_evidence jsonb NOT NULL DEFAULT '{}'::jsonb,approved_by uuid REFERENCES public.users(id) ON DELETE SET NULL,approved_at timestamptz,created_by uuid REFERENCES public.users(id) ON DELETE SET NULL,updated_by uuid REFERENCES public.users(id) ON DELETE SET NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS tenant.crm_partner_mdf_programs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,name text NOT NULL,budget_amount numeric(18,2) NOT NULL DEFAULT 0,currency_code char(3),period_start date,period_end date,status text NOT NULL DEFAULT 'active' CHECK(status IN('draft','active','closed')),rules jsonb NOT NULL DEFAULT '{}'::jsonb,created_by uuid REFERENCES public.users(id) ON DELETE SET NULL,updated_by uuid REFERENCES public.users(id) ON DELETE SET NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(organization_id,name));
CREATE TABLE IF NOT EXISTS tenant.crm_partner_mdf_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,program_id uuid,partner_party_id uuid,title text NOT NULL,amount numeric(18,2) NOT NULL CHECK(amount>0),currency_code char(3),status text NOT NULL DEFAULT 'submitted' CHECK(status IN('draft','submitted','approved','rejected','claimed','paid')),business_case text,evidence jsonb NOT NULL DEFAULT '{}'::jsonb,approved_by uuid REFERENCES public.users(id) ON DELETE SET NULL,approved_at timestamptz,created_by uuid REFERENCES public.users(id) ON DELETE SET NULL,updated_by uuid REFERENCES public.users(id) ON DELETE SET NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS tenant.crm_partner_incentive_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,partner_party_id uuid,deal_registration_id uuid,event_type text NOT NULL,basis_amount numeric(18,2) NOT NULL DEFAULT 0,rate_percent numeric(9,4) NOT NULL DEFAULT 0,incentive_amount numeric(18,2) NOT NULL DEFAULT 0,status text NOT NULL DEFAULT 'calculated' CHECK(status IN('calculated','approved','paid','reversed')),evidence jsonb NOT NULL DEFAULT '{}'::jsonb,created_by uuid REFERENCES public.users(id) ON DELETE SET NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS tenant.crm_field_sales_visits(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES public.users(id) ON DELETE RESTRICT,entity_type text NOT NULL CHECK(entity_type IN('lead','opportunity','party','contact','general')),entity_id uuid,purpose text,latitude numeric(9,6) NOT NULL CHECK(latitude BETWEEN -90 AND 90),longitude numeric(9,6) NOT NULL CHECK(longitude BETWEEN -180 AND 180),accuracy_meters numeric(12,2) NOT NULL DEFAULT 0,checked_in_at timestamptz NOT NULL,checked_out_at timestamptz,outcome text,evidence_hash text NOT NULL,created_by uuid REFERENCES public.users(id) ON DELETE SET NULL,updated_by uuid REFERENCES public.users(id) ON DELETE SET NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(checked_out_at IS NULL OR checked_out_at>=checked_in_at));
CREATE TABLE IF NOT EXISTS tenant.crm_sequence_branch_definitions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,sequence_id uuid,name text NOT NULL,version integer NOT NULL DEFAULT 1 CHECK(version>0),graph jsonb NOT NULL,status text NOT NULL DEFAULT 'active' CHECK(status IN('draft','active','inactive')),created_by uuid REFERENCES public.users(id) ON DELETE SET NULL,updated_by uuid REFERENCES public.users(id) ON DELETE SET NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(organization_id,sequence_id,name,version));
CREATE TABLE IF NOT EXISTS tenant.crm_coaching_scorecards(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,conversation_id uuid,coach_user_id uuid REFERENCES public.users(id) ON DELETE SET NULL,seller_user_id uuid REFERENCES public.users(id) ON DELETE SET NULL,score numeric(5,2) NOT NULL CHECK(score BETWEEN 0 AND 100),criteria jsonb NOT NULL,observations jsonb NOT NULL,feedback text,status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','published','acknowledged')),content_hash text NOT NULL,created_by uuid REFERENCES public.users(id) ON DELETE SET NULL,updated_by uuid REFERENCES public.users(id) ON DELETE SET NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS tenant.crm_gamification_programs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,name text NOT NULL,rules jsonb NOT NULL DEFAULT '[]'::jsonb,status text NOT NULL DEFAULT 'active' CHECK(status IN('draft','active','inactive')),period_start date,period_end date,created_by uuid REFERENCES public.users(id) ON DELETE SET NULL,updated_by uuid REFERENCES public.users(id) ON DELETE SET NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(organization_id,name));
CREATE TABLE IF NOT EXISTS tenant.crm_gamification_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,batch_id uuid NOT NULL,user_id uuid REFERENCES public.users(id) ON DELETE SET NULL,event_type text NOT NULL,points integer NOT NULL,evidence jsonb NOT NULL DEFAULT '{}'::jsonb,created_by uuid REFERENCES public.users(id) ON DELETE SET NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS tenant.crm_inbound_email_routes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,address text NOT NULL,route_type text NOT NULL CHECK(route_type IN('lead','opportunity','auto')),rules jsonb NOT NULL DEFAULT '{}'::jsonb,status text NOT NULL DEFAULT 'active' CHECK(status IN('active','inactive')),created_by uuid REFERENCES public.users(id) ON DELETE SET NULL,updated_by uuid REFERENCES public.users(id) ON DELETE SET NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(organization_id,address));
CREATE TABLE IF NOT EXISTS tenant.crm_inbound_email_conversions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,provider_message_id text NOT NULL,from_email text NOT NULL,subject text NOT NULL,routing_result jsonb NOT NULL,entity_type text NOT NULL,entity_id uuid,status text NOT NULL DEFAULT 'processed' CHECK(status IN('queued','processed','failed')),created_by uuid REFERENCES public.users(id) ON DELETE SET NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(organization_id,provider_message_id));
CREATE TABLE IF NOT EXISTS tenant.crm_partner_engagement_acceptance_evidence(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,capability_id text NOT NULL,commit_sha text NOT NULL,status text NOT NULL CHECK(status IN('passed','failed','blocked')),evidence jsonb NOT NULL DEFAULT '{}'::jsonb,evidence_hash text NOT NULL,verified_by uuid REFERENCES public.users(id) ON DELETE SET NULL,verified_at timestamptz NOT NULL DEFAULT now(),UNIQUE(organization_id,capability_id,commit_sha));
CREATE INDEX IF NOT EXISTS crm_partner_deals_status_idx ON tenant.crm_partner_deal_registrations(organization_id,status,created_at DESC);
CREATE INDEX IF NOT EXISTS crm_field_visits_user_idx ON tenant.crm_field_sales_visits(organization_id,user_id,checked_in_at DESC);
CREATE INDEX IF NOT EXISTS crm_gamification_user_idx ON tenant.crm_gamification_events(organization_id,user_id,created_at DESC);
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['crm_partner_portal_profiles','crm_partner_deal_registrations','crm_partner_mdf_programs','crm_partner_mdf_requests','crm_partner_incentive_events','crm_field_sales_visits','crm_sequence_branch_definitions','crm_coaching_scorecards','crm_gamification_programs','crm_gamification_events','crm_inbound_email_routes','crm_inbound_email_conversions','crm_partner_engagement_acceptance_evidence'] LOOP EXECUTE format('ALTER TABLE tenant.%I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('ALTER TABLE tenant.%I FORCE ROW LEVEL SECURITY',t); EXECUTE format('DROP POLICY IF EXISTS tenant_organization_isolation ON tenant.%I',t); EXECUTE format('CREATE POLICY tenant_organization_isolation ON tenant.%I USING (organization_id=current_setting(''app.current_organization_id'',true)::uuid) WITH CHECK (organization_id=current_setting(''app.current_organization_id'',true)::uuid)',t); END LOOP; END $$;
CREATE OR REPLACE FUNCTION tenant.crm_partner_engagement_immutable() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'CRM partner engagement evidence is immutable'; END $$;
DROP TRIGGER IF EXISTS crm_partner_engagement_acceptance_immutable ON tenant.crm_partner_engagement_acceptance_evidence; CREATE TRIGGER crm_partner_engagement_acceptance_immutable BEFORE UPDATE OR DELETE ON tenant.crm_partner_engagement_acceptance_evidence FOR EACH ROW EXECUTE FUNCTION tenant.crm_partner_engagement_immutable();
GRANT SELECT,INSERT,UPDATE,DELETE ON ALL TABLES IN SCHEMA tenant TO vercent_app;
COMMIT;
